mapper.update:
UPDATE notification
SET isRead = 1
WHERE userId = #{userId}
  AND isRead = 0
  AND id NOT IN (
    SELECT id FROM (
        SELECT id
        FROM notification
        WHERE userId = #{userId}
          AND isRead = 0
        ORDER BY createTime DESC, id DESC
        LIMIT #{keepCount}
    ) keep_rows
)

mapper.delete:
